var buildGradeTable = (semester, gradeLabel) => {
  const isMorning = gradeLabel === "11, 12";
  const session = isMorning ? "S\xE1ng" : "Chi\u1EC1u";
  const rows = examDays.flatMap((day) => day.exams.map((exam) => {
    const date = semester === 1 ? day.dateI : day.dateII;
    const time = isMorning ? exam.timeMorning : exam.timeAfternoon;
    return `| ${day.weekday}, ${date} | ${session} | ${time} | ${exam.subject} | ${gradeLabel} | ${exam.duration} | ${exam.note} |`;
  }));
  const fromDate = semester === 1 ? "02/11" : "08/03";
  const toDate = semester === 1 ? "06/11/2026" : "12/03/2027";
  return [
    `\u0110\u1ECBa \u0111i\u1EC3m: \u0110i\u1EC3m ch\xEDnh. \u0110\u1ED1i t\u01B0\u1EE3ng: Kh\u1ED1i ${gradeLabel}. Bu\u1ED5i ki\u1EC3m tra: ${session.toLowerCase()}.`,
    "",
    "| Th\u1EE9, ng\xE0y | Bu\u1ED5i | Th\u1EDDi gian l\xE0m b\xE0i | M\xF4n ki\u1EC3m tra | Kh\u1ED1i l\u1EDBp | Th\u1EDDi l\u01B0\u1EE3ng | Ghi ch\xFA |",
    "|:----------|:----:|:-----------------:|:------------|:--------:|:----------:|:--------|",
    ...rows,
    "",
    "* L\u01B0u \xFD t\u1ED5 ch\u1EE9c:",
    "- H\u1ECDc sinh ch\u1EC9 ki\u1EC3m tra m\xF4n l\u1EF1a ch\u1ECDn m\xECnh \u0111ang h\u1ECDc; ri\xEAng c\xE1c m\xF4n gh\xE9p l\u1EF1a ch\u1ECDn c\u1EA7n b\u1ED1 tr\xED ph\xF2ng v\xE0 \u0111\u1EC1 ki\u1EC3m tra ri\xEAng, d\xF9 c\xF9ng khung gi\u1EDD.",
    "- H\u1ECDc sinh c\xF3 m\u1EB7t tr\u01B0\u1EDBc gi\u1EDD ph\xE1t \u0111\u1EC1 t\u1ED1i thi\u1EC3u 20 ph\xFAt \u0111\u1EC3 \u1ED5n \u0111\u1ECBnh v\u1ECB tr\xED v\xE0 nghe ph\u1ED5 bi\u1EBFn quy ch\u1EBF.",
    `- C\xE1c m\xF4n ki\u1EC3m tra t\u1EA1i l\u1EDBp th\u1EF1c hi\u1EC7n theo th\u1EDDi kh\xF3a bi\u1EC3u ch\xEDnh kh\xF3a t\u1EEB ng\xE0y ${fromDate} \u0111\u1EBFn ng\xE0y ${toDate}.`,
    "- Ng\xE0y, ca v\xE0 gi\u1EDD trong b\u1EA3ng l\xE0 ph\u01B0\u01A1ng \xE1n d\u1EF1 th\u1EA3o c\u1EE7a nh\xE0 tr\u01B0\u1EDDng; t\u1ED5 chuy\xEAn m\xF4n r\xE0 so\xE1t theo k\u1EBF ho\u1EA1ch d\u1EA1y h\u1ECDc th\u1EF1c t\u1EBF v\xE0 tr\xECnh Hi\u1EC7u tr\u01B0\u1EDFng ph\xEA duy\u1EC7t tr\u01B0\u1EDBc khi ban h\xE0nh."
  ].join("\n");
};
DRAFT_SCHEDULE_ADJUSTMENT.sections[1].content = buildGradeTable(1, "11, 12");
